<script setup>
import Quantity from './Quantity.vue';
import SitePicker from './SitePicker.vue';
import Field from './Field.vue';
import PathInput from './PathInput.vue';
import {contract} from './schema.mjs';
const props=defineProps({group:String,section:{type:String,default:'all'},modelValue:Object,api:Object,readonly:Boolean});
const emit=defineEmits(['update:modelValue']);
const set=(key,value)=>emit('update:modelValue',{...props.modelValue,[key]:value});
</script>

<template><section>
 <template v-if="group==='candidates'&&['all','search'].includes(section)"><section class="sb-form-section"><h4>站点与搜索</h4><SitePicker :api="api" :model-value="modelValue.site_ids" :readonly="readonly" @update:model-value="set('site_ids',$event)"/><p v-if="!modelValue.site_ids.length" class="sb-muted">尚未授权搜索站点。</p><div class="sb-grid"><label>搜索名称来源<select :value="modelValue.query_scope" :disabled="readonly" @change="set('query_scope',$event.target.value)"><option value="trusted_aliases">原名与已经核实的别名</option><option value="original">仅原名</option></select></label><Quantity label="候选刷新间隔" :model-value="modelValue.refresh_seconds" :min="1" :max="86400" :readonly="readonly" @update:model-value="set('refresh_seconds',$event)"/></div></section><details class="sb-content-group sb-disclosure"><summary><span><strong>搜索上限与排除</strong><small>请求数量、并发与排除时长</small></span></summary><div class="sb-grid"><Field v-for="key in ['keywords','pages','concurrency','results','requests','supplement_limit','exclusion_scope','exclusion_seconds']" :key="key" :name="key" :schema="contract.schemas.Candidates.properties[key]" :model-value="modelValue[key]" :readonly="readonly" @update:model-value="set(key,$event)"/><Quantity label="站点请求间隔" :model-value="modelValue.interval" :max="10" :readonly="readonly" @update:model-value="set('interval',$event)"/></div></details></template>

 <template v-if="group==='lifecycle'"><p class="sb-muted">为已收录作品继续寻找更好版本。填 0 天表示不限期限。</p><div class="sb-grid"><label v-for="[key,title] in [['movie_days','电影追踪期限（天）'],['tv_days','剧集追踪期限（天）']]" :key="key">{{title}}<input type="number" min="0" max="36500" step="1" :value="modelValue[key]" :disabled="readonly" @input="set(key,Number($event.target.value))"></label><label>期限从何时起算<select :value="modelValue.expiry_mode" :disabled="readonly" @change="set('expiry_mode',$event.target.value)"><option value="COMPLETE_COLLECTED">目标收集完成后</option><option value="LAST_INGEST">最后一次确认入库后</option></select></label><label>完结剧集的处理方式<select :value="modelValue.completed_mode" :disabled="readonly" @change="set('completed_mode',$event.target.value)"><option value="EPISODE">按集比较</option><option value="PACK">按整包比较</option></select></label><Quantity label="一次性机会时长" :model-value="modelValue.oneshot_seconds" :min="1" :readonly="readonly" @update:model-value="set('oneshot_seconds',$event)"/></div></template>

 <template v-if="group==='recovery'&&['all','schedule'].includes(section)"><section class="sb-form-section"><h4>检查计划</h4><div class="sb-grid"><Quantity v-for="[key,title] in [['reconcile_seconds','完整核对间隔'],['active_poll_seconds','在途目标检查间隔']]" :key="key" :label="title" :model-value="modelValue[key]" :min="1" :readonly="readonly" @update:model-value="set(key,$event)"/></div><label class="sb-check"><input type="checkbox" :checked="modelValue.watcher" :disabled="readonly" @change="set('watcher',$event.target.checked)">同时使用文件监听（定期核对仍保留）</label></section><section class="sb-form-section"><h4>每轮检查范围</h4><div class="sb-grid"><Field v-for="key in ['pages','entries']" :key="key" :name="key" :schema="contract.schemas.Recovery.properties[key]" :model-value="modelValue[key]" :readonly="readonly" @update:model-value="set(key,$event)"/><Quantity label="每轮核对最多耗时" :model-value="modelValue.seconds" :min="0.1" :max="30" :readonly="readonly" @update:model-value="set('seconds',$event)"/></div></section></template>
 <template v-if="group==='recovery'&&['all','exceptions'].includes(section)"><section class="sb-form-section"><h4>异常恢复</h4><label class="sb-toggle-row"><span><strong>启动后核对未完成处理</strong><small>先读取实际状态，再决定是否继续，避免重复交付。</small></span><input type="checkbox" :checked="modelValue.startup_reconcile" :disabled="readonly" @change="set('startup_reconcile',$event.target.checked)"></label><p>{{modelValue.consumer_recovery_ref?'已保留整理恢复记录；当前能否恢复仍以检查结果为准。':'尚无整理恢复记录。'}} </p></section></template>

 <template v-if="group==='safety'"><div class="sb-grid"><Quantity kind="bytes" label="本地磁盘至少保留" note="这是剩余空间阈值，不是可写目录授权。" :model-value="modelValue.minimum_free_bytes" :readonly="readonly" @update:model-value="set('minimum_free_bytes',$event)"/><Quantity label="网络请求超时" :model-value="modelValue.network_timeout" :min="1" :max="120" :readonly="readonly" @update:model-value="set('network_timeout',$event)"/><label>同时运行的工作数<input type="number" min="1" max="8" step="1" :value="modelValue.worker_limit" :disabled="readonly" @input="set('worker_limit',Number($event.target.value))"></label></div><section class="sb-form-section"><h4>授权试验目录</h4><p class="sb-muted">仅填写已经允许用于试验的绝对路径；不会自动推导或扩大范围。</p><div v-for="(path,index) in modelValue.test_roots" :key="index" class="sb-path-item"><PathInput label="试验根目录" :model-value="path" :readonly="readonly" @update:model-value="set('test_roots',modelValue.test_roots.map((p,i)=>i===index?$event:p))"/><VBtn variant="text" color="error" :disabled="readonly" @click="set('test_roots',modelValue.test_roots.filter((_,i)=>i!==index))">移除目录</VBtn></div><VBtn variant="tonal" :disabled="readonly" @click="set('test_roots',[...modelValue.test_roots,''])">添加试验目录</VBtn></section></template>
</section></template>
